using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.Dtos; using RaceDay.Api.Services; namespace RaceDay.Api.Controllers; [ApiController,Authorize,Route("api/users")] public class UsersController(RaceDayDbContext db):ControllerBase { [HttpGet("me")] public async Task<ActionResult<UserResponse>> Me(){var id=User.UserId();if(id==0)return Unauthorized();var u=await db.Users.FindAsync(id);if(u==null)return NotFound();return Ok(new UserResponse(u.UserId,u.FirstName,u.LastName,u.Email,u.Role,u.PhoneNumber,u.CreatedAt,u.ProfilePictureUrl));} [HttpPut("me")] public async Task<ActionResult<UserResponse>> Update(UpdateProfileRequest r){if(!ModelState.IsValid)return ValidationProblem(ModelState);var id=User.UserId();if(id==0)return Unauthorized();var u=await db.Users.FindAsync(id);if(u==null)return NotFound();var email=r.Email.Trim();if(await db.Users.AnyAsync(x=>x.Email==email&&x.UserId!=id))return Conflict(new{message="An account with this email already exists."});u.FirstName=r.FirstName.Trim();u.LastName=r.LastName.Trim();u.Email=email;u.PhoneNumber=r.PhoneNumber;await db.SaveChangesAsync();return Ok(new UserResponse(u.UserId,u.FirstName,u.LastName,u.Email,u.Role,u.PhoneNumber,u.CreatedAt,u.ProfilePictureUrl));} }